import { debounce } from 'lodash-es';
import { ActionType, Hooks, TableInstance, TableState } from 'react-table';

import { clampAll, filterHeaderGroupWidths } from './column-resize-utils.js';
import { useColumnsSizesActions } from '../use-column-sizes/actions.js';

const DEBOUNCE_TIME_MS = 300;

/** Reducer that handles resizing of the column */
function columnResizeReducer(
  state: TableState,
  action: ActionType,
  _previousState?: TableState,
  _instance?: TableInstance,
): TableState | undefined {
  if (_instance) {
    const { disableResizing, onColumnResize, allColumns, headers } = _instance;
    if (!disableResizing && typeof onColumnResize === 'function') {
      if (action.type === useColumnsSizesActions.columnDoneResizing) {
        const {
          columnResizing: { columnWidths: resizedColumnWidths },
        } = state;

        const filteredColumnWidths = filterHeaderGroupWidths(
          resizedColumnWidths,
          headers,
        );
        const newColumnWidths = clampAll(filteredColumnWidths, allColumns);

        if (Object.keys(newColumnWidths).length > 0) {
          if (_instance.onColumResizeDebounced === undefined) {
            _instance.onColumResizeDebounced = debounce(
              (newColumnWidths) => {
                requestAnimationFrame(() => {
                  onColumnResize(newColumnWidths);
                });
              },
              DEBOUNCE_TIME_MS,
              { leading: true, trailing: true },
            );
          }
          _instance.onColumResizeDebounced(newColumnWidths);
        }
      }

      return state;
    }
  }
}

/**
 * Table hook that enables setting column widths and triggers callback event or column resize.
 */
export function useColumnResizeHandler(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  hooks: Hooks<any>,
): void {
  hooks.stateReducers.push(columnResizeReducer);
}

useColumnResizeHandler.pluginName = 'useColumnResizeHandler';
